using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

// Define tools available to the agent
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up")] string query) =>
        {
            Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
            // Simulated web search results — replace with a real search API (e.g., Bing Search)
            return Task.FromResult(new[]
            {
                new SearchResult($"Result 1 for '{query}'", $"https://example.com/1?q={Uri.EscapeDataString(query)}",
                    $"Comprehensive overview of {query} covering key concepts, recent developments, and expert perspectives."),
                new SearchResult($"Result 2 for '{query}'", $"https://example.com/2?q={Uri.EscapeDataString(query)}",
                    $"Academic research findings on {query} including statistical data and peer-reviewed conclusions."),
                new SearchResult($"Result 3 for '{query}'", $"https://example.com/3?q={Uri.EscapeDataString(query)}",
                    $"Industry analysis of {query} with practical applications and case studies from leading organizations."),
            });
        },
        name: "web_search",
        description: "Search the web for information on a given query. Returns titles, URLs, and snippets."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for this note")] string heading,
         [Description("The content of the note")] string content) =>
        {
            notes.Add(heading, content);
            Console.WriteLine($"  [Notes] Saved note: \"{heading}\"");
            return $"Note saved: {heading}";
        },
        name: "take_note",
        description: "Save a research note with a heading and content. Use this to record important findings."),

    AIFunctionFactory.Create(
        () =>
        {
            var allNotes = notes.GetAll();
            return allNotes.Count == 0
                ? "No notes taken yet."
                : string.Join("\n\n", allNotes.Select(n => $"## {n.Heading}\n{n.Content}"));
        },
        name: "review_notes",
        description: "Retrieve all notes taken so far to review findings before summarizing."),
};

// Configure the agent
var agentOptions = new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. Your task is to research a topic thoroughly and produce a summary.

        Follow this workflow:
        1. Break the topic into 2-3 key sub-questions.
        2. Use web_search to find information for each sub-question.
        3. Use take_note to record important findings from each search.
        4. Use review_notes to see all your collected research.
        5. Provide a final comprehensive summary to the user.

        Be thorough but concise. Cite sources where possible.
        """,
    DefaultToolMode = ChatToolMode.Auto,
    Tools = tools,
};

var agent = new ChatClientAgent(chatClient, agentOptions);

// Get topic from user
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("       AI Research Agent (.NET 10)");
Console.WriteLine("═══════════════════════════════════════════");
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: \"{topic}\"\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

// Run the agent loop
await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n═══════════════════════════════════════════");
Console.WriteLine("Research complete. Notes collected:");
Console.WriteLine("═══════════════════════════════════════════");
foreach (var note in notes.GetAll())
{
    Console.WriteLine($"\n## {note.Heading}");
    Console.WriteLine(note.Content);
}

// Supporting types
record SearchResult(string Title, string Url, string Snippet);

class ResearchNotes
{
    private readonly List<Note> _notes = [];

    public void Add(string heading, string content) =>
        _notes.Add(new Note(heading, content));

    public IReadOnlyList<Note> GetAll() => _notes.AsReadOnly();

    public record Note(string Heading, string Content);
}

