using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();
services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(_ =>
    new OpenAI.OpenAIClient(apiKey)
        .GetChatClient(modelId)
        .AsIChatClient());

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();
var logger = serviceProvider.GetRequiredService<ILogger<Program>>();

// Create tools
var noteStore = new NoteStore();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(noteStore.WebSearch),
    AIFunctionFactory.Create(noteStore.TakeNote),
    AIFunctionFactory.Create(noteStore.ReviewNotes),
};

// Configure the agent
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your task is to research a topic thoroughly and produce a summary.

        Follow this workflow:
        1. Break the topic into 2-3 key sub-questions.
        2. Use WebSearch to find information for each sub-question.
        3. Use TakeNote to record important findings from each search.
        4. Use ReviewNotes to see all your collected research.
        5. Provide a final comprehensive summary to the user.

        Be thorough but concise. Cite sources where possible.
        """,
    name: "ResearchAgent",
    tools: tools);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("       AI Research Agent (.NET 10)");
Console.WriteLine("═══════════════════════════════════════════");
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: \"{topic}\"\n");

try
{
    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    });

    var session = await agent.CreateSessionAsync(Guid.NewGuid().ToString());

    var response = await agent.RunAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        session,
        runOptions);

    Console.WriteLine(response.Text);
}
catch (Exception ex)
{
    logger.LogError(ex, "Agent execution failed");
    Console.WriteLine($"\nError: {ex.Message}");
}

Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine("Research notes collected:");
Console.WriteLine("═══════════════════════════════════════════");
foreach (var note in noteStore.GetAllNotes())
{
    Console.WriteLine($"\n## {note.Heading}");
    Console.WriteLine(note.Content);
}

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class NoteStore
{
    private readonly List<(string Heading, string Content)> _notes = [];

    [Description("Searches the web for information about a query. Returns relevant search results with titles, URLs, and summaries.")]
    public string WebSearch(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Simulated web search — replace with a real search API (e.g., Bing Search, Google Custom Search)
        return $"""
            Search results for: "{query}"

            1. [Encyclopedia] Comprehensive overview of {query}
               URL: https://example.com/wiki/{Uri.EscapeDataString(query)}
               Summary: Foundational information covering key concepts, history, and definitions related to {query}.

            2. [Academic Research] Peer-reviewed findings on {query}
               URL: https://example.com/research/{Uri.EscapeDataString(query)}
               Summary: Data-driven analysis with statistical evidence, methodologies, and conclusions about {query}.

            3. [Industry Analysis] Practical applications of {query}
               URL: https://example.com/industry/{Uri.EscapeDataString(query)}
               Summary: Real-world case studies, current trends, and expert perspectives on {query}.
            """;
    }

    [Description("Save a research note with a heading and content. Use this to record important findings during research.")]
    public string TakeNote(
        [Description("A concise heading for this note")] string heading,
        [Description("The detailed content of the note")] string content)
    {
        _notes.Add((heading, content));
        Console.WriteLine($"  📝 Note saved: \"{heading}\"");
        return $"Note saved: \"{heading}\" ({_notes.Count} total notes).";
    }

    [Description("Retrieve all notes taken so far to review findings before writing a summary.")]
    public string ReviewNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  📋 Reviewing {_notes.Count} notes");
        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note {i + 1} - {n.Heading}:\n{n.Content}"));
    }

    public IReadOnlyList<(string Heading, string Content)> GetAllNotes() => _notes.AsReadOnly();
}

